import{z as A,x as d,o as E,c as B,q as o,j as l,D as t,d as n,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"卫星到特征","description":"","frontmatter":{"title":"卫星到特征","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/satellite-to-feature.md","filePath":"quant/satellite-to-feature.md","lastUpdated":1791413859000}'),p={name:"quant/satellite-to-feature.md"};function u(h,a,m,D,f,c){const r=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=o('<h1 id="卫星到特征" tabindex="-1">卫星到特征 <a class="header-anchor" href="#卫星到特征" aria-label="Permalink to &quot;卫星到特征&quot;">​</a></h1><div class="epigraph"><p>像素不是 alpha。从轨道影像到证券特征，要经过传感器校准、云与缺失、设施检测、映射与 vintage；每一步都在改写你实际交易的对象。</p><footer>—— Henderson, Storeygard and Weil, Measuring Economic Growth from Outer Space, AER, 2012；Donaldson and Storeygard, The View from Above, JEP, 2016</footer></div><p><a href="/quant/satellite-geo">卫星与地理</a>已经说明夜灯、NDVI、设施影像各自测什么。<a href="/quant/alt-panel-construction">面板构造</a>要求映射与缺失机制。本课的缺口是中间那一段：<strong>栅格 → 物体 → 数量 → 特征</strong>，以及传感器世代与处理延迟如何进入可交易时钟。不要重讲夜灯与 GDP 的宏观回归，只补生产特征管道。下一课合规会限制高分辨率影像能识别到什么粒度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原始输入是带时间戳的栅格或商业供应商的「车辆计数」。研究若直接拿计数对收益回归，跳过了：几何校正、云掩膜、传感器切换（DMSP→VIIRS）、检测模型版本、以及计数到公司的归属。每一跳都有回填：新检测模型重跑历史影像，计数被改写。本课把管道显式化，使<a href="/quant/alt-data-backfill-bias">回填</a>有可版本化的节点。</p><p>设施检测把像素变成物体。物体计数的误差在繁忙停车场与空旷矿区不同，异方差会进入截面。特征若用「相对上年同期」，还依赖当时是否已有上年同期的<strong>当时版本</strong>计数，而不是终版。</p><p><span class="marginnote">数字实例：检测模型在空旷矿区数矿车，误差可能只有 ±2 辆；在周末爆满的停车场数轿车，重叠与遮挡能让误差到 ±30 辆且方向相关。同样「一辆算一辆」，两处信噪比差一个量级——特征必须带覆盖与质量标记，让模型知道哪些计数可信。</span></p><h3 id="公开传感器与商业计数不是同一管道" tabindex="-1">公开传感器与商业计数不是同一管道 <a class="header-anchor" href="#公开传感器与商业计数不是同一管道" aria-label="Permalink to &quot;公开传感器与商业计数不是同一管道&quot;">​</a></h3><p>VIIRS 夜灯可复现、延迟和算法有文献。商业停车场计数不可完全复现，必须把供应商模型版本写进 vintage。把两者混成「卫星因子」，无法验证。公开宏观代理适合国家/区域 nowcast；商业设施适合公司层面，也更贵、覆盖更偏、回填更严重。</p><p><span class="marginnote">云层与季风相关，缺测不是随机。面板课已禁止把 NA 当零；卫星管道必须把云掩膜作为一等输出，而不是只输出一个计数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>管道节点：(1) 影像 ingest 与传感器元数据；(2) 云/质量掩膜；(3) 校准与跨卫星交叉校准；(4) 检测或指数计算（NDVI、夜间灯光、物体计数）；(5) 空间聚合到当时门店/设施多边形；(6) 映射到证券；(7) 延迟对齐到决策日。每个节点输出存档，禁止只存最终特征。特征建议用相对量：同比、相对同业、相对自身滚动中位，并控制覆盖（有效像素比例）。Addoum、Ng 与 Ortiz-Bobea 一类工作把温度对齐到经营场所，精神是空间到公司的可审计映射，而不是「我们有图」。</p><p>验证：与公开披露的同店、产量、USDA/EIA 对照，看的是代理质量，不是看能否在样本内预测股价。能预测股价但与物理量无关，更像数据挖掘或回填。</p><p><span class="marginnote">直觉类比：验证卫星特征像核对新实习生的报表——先拿它和已知的官方数字（同店、USDA、EIA）对一对，确认它在如实转述物理世界；跳过这步直接问「能不能预测股价」，等于只看实习生会不会猜中彩票号码，猜中了也分不清是真本事还是提前看了答案（回填）。</span></p><h3 id="从特征到持有期" tabindex="-1">从特征到持有期 <a class="header-anchor" href="#从特征到持有期" aria-label="Permalink to &quot;从特征到持有期&quot;">​</a></h3><p>卫星重访可能是数日一次。特征的自然 \\(H\\) 不是日内。硬做成日频信号，信息来自填充规则。体制卡应把卫星策略标成中低频，执行可以在财报窗加密，但信号时钟仍是重访时钟。这与持有期课的 \\(\\tau\\) 对齐一致。</p>',16)),(E(),l(s,null,{default:t(()=>[i(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20LR%0A%20%20RV%5B%22%E5%8D%AB%E6%98%9F%E9%87%8D%E8%AE%BF%3A%20%E6%95%B0%E6%97%A5%E4%B8%80%E6%AC%A1%22%5D%20--%3E%20FEAT%5B%22%E7%89%B9%E5%BE%81%E6%97%B6%E9%92%9F%22%5D%0A%20%20DLY%5B%22%E5%A4%84%E7%90%86%E5%BB%B6%E8%BF%9F%3A%20%E4%B8%8B%E8%A1%8C%E4%B8%8E%E5%8E%BB%E4%BA%91%201-3%20%E5%A4%A9%22%5D%20--%3E%20FEAT%0A%20%20FEAT%20--%3E%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E6%97%B6%E9%92%9F%3A%20%E4%B8%AD%E4%BD%8E%E9%A2%91%22%5D%0A%20%20SIG%20--%3E%20DEC%5B%22%E5%86%B3%E7%AD%96%E6%97%A5%3A%20%E5%8F%AA%E7%94%A8%E5%BD%93%E6%97%B6%20vintage%22%5D%0A%20%20DEC%20--%3E%20EXE%5B%22%E6%89%A7%E8%A1%8C%E5%8F%AF%E5%9C%A8%E8%B4%A2%E6%8A%A5%E7%AA%97%E5%8A%A0%E5%AF%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"测量误差进入收益回归，像错误变量，把系数拉向零；回填则把系数拉向虚假显著。两者方向相反，终版回归无法诊断。节点存档才能做：用当时检测模型 vs 今日模型重跑的差。传感器切换造成水平跳动，若不交叉校准，体制切换会被当成经济断点。Donaldson–Storeygard 强调这一点，金融应用同样适用。",-1)),a[5]||(a[5]=e("p",null,"价格发现：若 USDA 已发布，NDVI 的增量信息下降。特征应标明信息集对照——相对官方统计的残差，才可能是增量。否则卫星只是把已公开信息换一种采样。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"高分辨率屋顶与车辆可以接近个人识别。特征必须停在设施统计量。下一课把这条写成合规约束，而不是写成精度目标。")],-1)),(E(),l(s,null,{default:t(()=>[i(r,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20LR%0A%20%20IMG%5B%22%E5%BD%B1%E5%83%8F%20%2B%20%E4%BC%A0%E6%84%9F%E5%99%A8%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20QA%5B%22%E4%BA%91%E4%B8%8E%E8%B4%A8%E9%87%8F%E6%8E%A9%E8%86%9C%22%5D%0A%20%20QA%20--%3E%20DET%5B%22%E6%8C%87%E6%95%B0%E6%88%96%E7%89%A9%E4%BD%93%E6%A3%80%E6%B5%8B%22%5D%0A%20%20DET%20--%3E%20FAC%5B%22%E5%BD%93%E6%97%B6%E8%AE%BE%E6%96%BD%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%0A%20%20FAC%20--%3E%20SEC%5B%22%E6%98%A0%E5%B0%84%E5%88%B0%E8%AF%81%E5%88%B8%22%5D%0A%20%20SEC%20--%3E%20PIT%5B%22%E5%86%B3%E7%AD%96%E6%97%A5%E7%89%B9%E5%BE%81%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h3 id="同比特征仍依赖当时版本的上年计数" tabindex="-1">同比特征仍依赖当时版本的上年计数 <a class="header-anchor" href="#同比特征仍依赖当时版本的上年计数" aria-label="Permalink to &quot;同比特征仍依赖当时版本的上年计数&quot;">​</a></h3><p>相对上年同期看起来消除了水平，但若上年计数是今日模型重跑的，同比仍含回填。每个滞后期都要取当时 vintage，而不是取终版再差分。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SAR、光学、夜灯物理不同，不能同一套云规则。本课不涉及如何购买或处理未授权影像。加密与宏观商品期货对农业特征的定价已部分有效，增量 IC 可能接近零，这是边界不是失败。</p><p><span class="marginnote">常见误区：初学者容易以为「分辨率越高越好」。实际上分辨率越高越贵、覆盖越偏、越逼近个人识别红线，回填也越凶——供应商换个检测模型，十年历史全部改写。研究价值常常在免费、粗糙、可复现的公开传感器上，因为它至少允许你把 vintage 讲清楚。</span></p><p><span class="marginnote">公开夜灯与商业停车场计数不是同一管道。混成「卫星因子」之后，无法验证传感器校准，也无法把回填定位到节点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>卫星特征管道必须节点存档，才能版本化、才能测回填。</li><li>云掩膜与覆盖是特征，不是麻烦。</li><li>传感器世代要交叉校准，否则水平跳动像体制。</li><li>信号时钟跟重访走，不要假日频。</li><li>增量信息相对官方统计来定义。</li><li>出处：Henderson, Storeygard and Weil, <em>AER</em>, 2012；Chen and Nordhaus, 2011；Donaldson and Storeygard, <em>JEP</em>, 2016；公司对齐见 Addoum, Ng and Ortiz-Bobea, 2020。</li></ul>',8))])}const b=A(p,[["render",u]]);export{S as __pageData,b as default};
